let cloud = null;
const KEY='waystep.trips.v1', palette=['#dbeafe','#dce8ff','#d9f0ff','#e4e5ff','#e0edfa'], legacyPalette={'#dce6d0':'#dbeafe','#e8ddc5':'#dce8ff','#d8e6e9':'#d9f0ff','#e8d9dc':'#e4e5ff','#dddff0':'#e0edfa'};
const modes={walk:'Walking',bicycle:'Bicycle',car:'Car',taxi:'Taxi / rideshare',bus:'Bus',train:'Train',ferry:'Ferry',flight:'Flight',other:'Other'};
const symbols={walk:'↟',bicycle:'◉',car:'↗',taxi:'↗',bus:'▣',train:'▥',ferry:'≈',flight:'✈',other:'◇'};
const uid=()=>crypto.randomUUID();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let trips=[],active=null,filter='active',query='',hideDone=false,dragId=null,installPrompt=null,storageOK=true,firstVisit=false;
const app=document.querySelector('#app'), editor=document.querySelector('#editor');
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4200)}
function validate(data, preserveIds=false){const usedTrips=new Set();const safeId=(value,used)=>{const id=preserveIds&&typeof value==='string'&&/^[a-z0-9_-]{1,80}$/i.test(value)&&!used.has(value)?value:uid();used.add(id);return id};if(!data||!Array.isArray(data.trips)||data.trips.length>500)throw Error('Choose a Waystep backup containing a trips list.');const str=(v,n=2000)=>typeof v==='string'?v.slice(0,n):'';return data.trips.map(t=>{if(!t||typeof t.title!=='string'||!t.title.trim()||!Array.isArray(t.steps)||t.steps.length>1000)throw Error('The backup contains an invalid trip.');const usedSteps=new Set();return{id:safeId(t.id,usedTrips),title:str(t.title,200),notes:str(t.notes,5000),start:str(t.start,10),end:str(t.end,10),color:palette.includes(t.color)?t.color:(legacyPalette[t.color]||palette[0]),archived:!!t.archived,example:!!t.example,steps:t.steps.map(s=>{if(!s||typeof s.title!=='string'||!s.title.trim())throw Error('The backup contains an invalid step.');const v={id:safeId(s.id,usedSteps),title:str(s.title,200),mode:Object.hasOwn(modes,s.mode)?s.mode:'other',done:!!s.done};for(const k of ['from','to','service','departure','arrival','booking','notes'])v[k]=str(s[k],k==='notes'?5000:1000);return v})}})}
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);trips=validate(data,true)}else firstVisit=raw===null}catch(e){storageOK=false;toast('Saved plans could not be loaded. Export or recover browser data before making changes.');}
function commit(next){if(cloud?.active)return cloud.save(trips,next);if(!storageOK){toast('Saving is unavailable. Reload or recover your saved data first.');return false}try{localStorage.setItem(KEY,JSON.stringify({version:1,trips:next}));trips=next;return true}catch{toast('Could not save changes. Storage may be full or disabled. Export a backup.');return false}}
function mutate(fn){const copy=structuredClone(trips);fn(copy);if(commit(copy)){render();return true}return false}
const trip=()=>trips.find(t=>t.id===active);
function date(d){if(!d||!/^\d{4}-\d{2}-\d{2}$/.test(d))return '';const x=new Date(d+'T12:00:00');return Number.isNaN(+x)?'':x.toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'})}
function when(d){if(!d)return '';const x=new Date(d);return Number.isNaN(+x)?esc(d):x.toLocaleString('en-AU',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})}
const dates=t=>t.start?date(t.start)+(t.end?' – '+date(t.end):''):'Dates to be decided';
const completed=t=>t.steps.filter(s=>s.done).length;
const progress=t=>t.steps.length?Math.round(100*completed(t)/t.steps.length):0;
function mapTarget(s){
  const origin=(s.from||'').trim(),destination=(s.to||'').trim();
  const travelModes={walk:'walking',bicycle:'bicycling',car:'driving',taxi:'driving',bus:'transit',train:'transit',ferry:'transit'};
  const mode=travelModes[s.mode];
  if(origin&&destination&&origin!==destination&&mode){
    return {url:`https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(destination)}&travelmode=${mode}`,label:'View route',description:`Show ${modes[s.mode].toLowerCase()} directions from ${origin} to ${destination}`,hint:mode==='transit'?'Opens public transport route options. Confirm the service and travel date in Google Maps.':'Opens directions for this step. Google Maps chooses the available route.'};
  }
  return {url:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(destination)}`,label:s.mode==='flight'?'Arrival airport':'Map location',description:`Open ${destination} in maps`,hint:s.mode==='flight'?'Shows the arrival airport. Google Maps directions links do not support flight paths.':!origin?'Add a starting location to this step to show route directions.':'Shows this destination on the map.'};
}

function syncButton(){
  return cloud
    ? '<button class="btn" data-action="cloud-account">' + esc(cloud.label) + '</button>'
    : '';
}

function render(){const t=trip();app.innerHTML=`<div class="shell"><aside class="sidebar"><div><div class="brand"><img src="icon.svg" alt="">Waystep<span style="color:#4387f0">.</span></div><div class="tagline">A little planning. A lot of possibility.</div></div><nav class="nav" aria-label="Trips"><button data-action="library" class="${filter==='active'?'active':''}">▦ &nbsp; My trips <span class="count">${trips.filter(t=>!t.archived).length}</span></button><button data-action="archives" class="${filter==='archive'?'active':''}">▱ &nbsp; Archived <span class="count">${trips.filter(t=>t.archived).length}</span></button></nav><div class="side-bottom"><button data-action="export">↗ &nbsp; Export backup</button><button data-action="import">↙ &nbsp; Import backup</button><button data-action="help">? &nbsp; Help & install</button></div></aside><main class="main"><div class="topbar"><span>${t?'MY TRIPS / YOUR JOURNEY':'YOUR PERSONAL TRAVEL PLANNER'}</span><div class="topbar-actions">${syncButton()}<span class="pill">${navigator.onLine?'● Ready to explore':'● Offline mode'}</span></div></div>${t?journey(t):library()}<div class="mobile-tools"><button class="btn" data-action="export">Export backup</button><button class="btn" data-action="import">Import backup</button><button class="btn" data-action="help">Help & install</button></div></main></div>`;bindDrag()}
function library(){const list=trips.filter(t=>t.archived===(filter==='archive')).filter(t=>(t.title+' '+t.notes).toLowerCase().includes(query.toLowerCase()));return `<header class="hero"><div><div class="eyebrow">Make room for adventure</div><h1>${filter==='archive'?'Trips to remember.':'Where to next?'}</h1><p class="sub">Every great journey starts with a little plan.</p></div><div class="hero-buttons"><button class="btn primary" data-action="ai-plan">✦ Plan with AI</button><button class="btn" data-action="new-trip">＋ New trip</button></div></header><div class="toolbar"><span class="sub">${filter==='archive'?'Your archived trips':'Your trips'} <span style="color:#3b4b60">/ ${list.length}</span></span><input id="search" class="search" aria-label="Search trips" placeholder="⌕  Search your trips…" value="${esc(query)}"></div><div class="grid">${list.map(t=>`<article class="trip"><div class="trip-cover" style="--tint:${t.color}"><div class="landscape" aria-hidden="true"></div><button class="icon-btn cover-icon" data-action="open" data-id="${t.id}" aria-label="Open ${esc(t.title)}">${t.steps.some(s=>s.mode==='flight')?'✈':'↗'}</button><span class="cover-label">${t.example?'Example itinerary':t.archived?'Saved memories':'A journey of your own'}</span></div><div class="trip-body"><button class="trip-title" data-action="open" data-id="${t.id}">${esc(t.title)}</button><div class="date">◷ &nbsp;${esc(dates(t))}</div><p class="trip-notes">${esc(t.notes||'Your next adventure is taking shape.')}</p><div class="progress" aria-label="${progress(t)}% completed"><span style="width:${progress(t)}%"></span></div><div class="trip-footer"><span>${completed(t)} of ${t.steps.length} steps completed</span><div><button class="icon-btn" data-action="edit-trip" data-id="${t.id}" aria-label="Edit ${esc(t.title)}">Edit</button><button class="icon-btn" data-action="duplicate" data-id="${t.id}" aria-label="Duplicate ${esc(t.title)}">Copy</button></div></div><button class="btn open-trip" data-action="open" data-id="${t.id}">Open trip →</button></div></article>`).join('')}${filter==='active'?`<button class="new-card" data-action="new-trip"><span class="plus">＋</span><strong>A new adventure</strong><span>Start with a destination. Add the steps.</span></button>`:''}</div>${!list.length&&filter==='archive'?'<div class="empty"><h2>No archived trips yet</h2><p>Archive a trip from its journey screen to keep it here.</p></div>':''}<div class="tip"><span style="font-size:25px">✧</span><div><strong>Less juggling. More journey.</strong>Add each connection, address and booking in one place. Tick off the steps as you go.<button class="icon-btn" data-action="example">Load a detailed example trip ↗</button></div></div>`}
function journey(t){const next=t.steps.find(s=>!s.done);return `<div style="margin-top:24px"><button class="back" data-action="back">← Back to trips</button></div><header class="hero trip-hero"><div><div class="eyebrow">${t.example?'Example itinerary · enter your own services & times':'Your journey, one step at a time'}</div><h1>${esc(t.title)}</h1><p class="sub" style="white-space:pre-wrap">${esc(t.notes)}</p><div class="trip-meta"><span>◷ ${esc(dates(t))}</span>${t.archived?'<span class="pill">Archived</span>':''}<span>${cloud?.active?esc(cloud.label):'✓ Saved on this device'}</span></div></div><div class="actions"><button class="btn ai-button" data-action="ai-plan">✦ Add steps with AI</button><button class="btn primary" data-action="new-step">＋ Add travel step</button><button class="btn" data-action="edit-trip" data-id="${t.id}">Edit trip</button><button class="btn" data-action="print">Print</button><button class="btn" data-action="archive">${t.archived?'Restore':'Archive'}</button><button class="icon-btn" data-action="delete-trip" aria-label="Delete trip">Delete</button></div></header><div class="journey-layout"><section aria-label="Journey checklist"><div class="journey-head"><h2>Your travel steps <span style="font-size:16px;color:#3b4b60;font-weight:500">/ ${t.steps.length}</span></h2><label class="toggle"><input type="checkbox" id="hide-done" ${hideDone?'checked':''}> Hide completed</label></div>${t.steps.filter(s=>!hideDone||!s.done).map(s=>stepView(s,t,next)).join('')}${!t.steps.length?'<div class="empty"><div class="eyebrow">Trip created · Next, add your route</div><h2>Where does your journey begin?</h2><p>Start with a walk to the station, a flight, or any stop along the way.<br>You can add times and booking details later.</p><button class="btn primary" data-action="new-step">＋ Add your first step</button></div>':hideDone&&t.steps.every(s=>s.done)?'<div class="empty"><h2>You’ve arrived!</h2><p>Every step is complete. Uncheck “Hide completed” to see your journey.</p></div>':''}<button class="btn primary" style="margin-top:15px" data-action="new-step">＋ Add travel step</button><p class="drag-hint">Change your route anytime. Drag a step, or tap Move up / Move down.</p></section></div>`}
function stepView(s,t,next){const idx=t.steps.indexOf(s),map=mapTarget(s);return `<article class="step ${s.done?'done':''} ${s===next?'next':''}" data-step="${s.id}" draggable="true"><div class="step-top"><input class="step-check" type="checkbox" data-check="${s.id}" aria-label="Mark ${esc(s.title)} complete" ${s.done?'checked':''}><div class="step-main">${s===next?'<div class="next-label">UP NEXT</div>':''}<div class="step-number">STEP ${String(idx+1).padStart(2,'0')}</div><div class="step-name">${esc(s.title)}</div><div class="step-mode">${symbols[s.mode]} ${modes[s.mode]}${s.service?' · '+esc(s.service):''}</div></div><div class="step-actions"><button class="icon-btn move-btn" data-action="up" data-id="${s.id}" aria-label="Move ${esc(s.title)} up" ${idx===0?'disabled':''}>↑ <span>Move up</span></button><button class="icon-btn move-btn" data-action="down" data-id="${s.id}" aria-label="Move ${esc(s.title)} down" ${idx===t.steps.length-1?'disabled':''}>↓ <span>Move down</span></button><button class="icon-btn" data-action="edit-step" data-id="${s.id}">Edit</button><button class="icon-btn" data-action="delete-step" data-id="${s.id}" aria-label="Delete ${esc(s.title)}">×</button></div></div><div class="step-details">${s.from||s.to?`<div class="route">${s.from?`<span class="dot">○</span><span><span class="route-label">From</span> ${esc(s.from)}</span>`:''}${s.to?`<span class="dot">●</span><span><span class="route-label">To</span> ${esc(s.to)} &nbsp;<a href="${esc(map.url)}" target="_blank" rel="noopener noreferrer" title="${esc(map.hint)}" aria-label="${esc(map.description)}">${map.label} ↗</a></span>`:''}</div>`:''}${s.departure||s.arrival?`<div class="time-row">${s.departure?`<span>Departs ${when(s.departure)}</span>`:''}${s.arrival?`<span>Arrives ${when(s.arrival)}</span>`:''}</div>`:''}${s.notes||s.booking?`<details><summary>Notes & booking details</summary>${s.booking?`<p><strong>Booking:</strong> ${esc(s.booking)}</p>`:''}${s.notes?`<p>${esc(s.notes)}</p>`:''}</details>`:''}</div></article>`}
function showDialog(title,body,handler){editor.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-close aria-label="Close dialog">✕</button></div>${body}`;editor.querySelector('[data-close]').onclick=()=>editor.close();if(!editor.open)editor.showModal();const f=editor.querySelector('form');if(f)f.onsubmit=e=>{e.preventDefault();handler(new FormData(f))};editor.querySelector('[data-cancel]')?.addEventListener('click',()=>editor.close())}
function field(label,name,value='',type='text',full=false,extra=''){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
const footer='<div class="form-footer"><button type="button" class="btn" data-cancel>Cancel</button><button class="btn primary" type="submit">Save</button></div>';
function tripEditor(id){const t=trips.find(t=>t.id===id)||{title:'',notes:'',start:'',end:'',color:palette[0]};showDialog(id?'Edit your trip':'A new adventure',`<form><div class="fields">${field('Trip title *','title',t.title,'text',true,'required maxlength="200" placeholder="e.g. Brisbane → Wollongong"')}${field('Start date','start',t.start,'date')}${field('End date','end',t.end,'date')}<label class="field full">A little about this trip<textarea name="notes" maxlength="5000" placeholder="What’s the plan?">${esc(t.notes)}</textarea></label><div class="field full">Trip colour<div class="swatches">${palette.map(c=>`<button type="button" class="swatch ${c===t.color?'selected':''}" style="background:${c}" data-color="${c}" aria-label="${({'#dbeafe':'Cloud blue','#dce8ff':'Cornflower','#d9f0ff':'Sky','#e4e5ff':'Periwinkle','#e0edfa':'Ice blue'})[c]}" aria-pressed="${c===t.color}"></button>`).join('')}</div><input type="hidden" name="color" value="${t.color}"></div></div>${id?footer:footer.replace('>Save</button>','>Create trip &amp; add steps</button>')}</form>`,f=>{if(!f.get('title').trim()){toast('Give your trip a title.');return}if(f.get('start')&&f.get('end')&&f.get('end')<f.get('start')){toast('The end date must be on or after the start date.');return}const data=Object.fromEntries(f);data.title=data.title.trim();const newId=id||uid();if(mutate(ts=>{if(id)Object.assign(ts.find(x=>x.id===id),data);else ts.unshift({...data,id:newId,archived:false,steps:[]})})){editor.close();if(!id){active=newId;hideDone=false;filter='active';query='';render();stepEditor()}else toast('Trip saved')}});editor.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{editor.querySelector('[name=color]').value=b.dataset.color;editor.querySelectorAll('[data-color]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)})})}
function stepEditor(id){
  const s=trip().steps.find(s=>s.id===id)||{title:'',mode:'train'};
  const hasDetails=['from','service','departure','arrival','booking','notes'].some(k=>s[k]);
  showDialog(id?'Edit travel step':'Add a travel step',`<form><p class="editor-intro">${id?'Update this part of your journey.':'What’s the next part of your journey? Start with the basics.'}</p><div class="fields">
    ${field('Step title *','title',s.title,'text',true,'required maxlength="200" placeholder="e.g. Take the train to Wollongong"')}
    <label class="field full">Transport<select name="mode">${Object.entries(modes).map(([k,v])=>`<option value="${k}" ${s.mode===k?'selected':''}>${v}</option>`).join('')}</select></label>
    ${field('Destination / address','to',s.to,'text',true,'maxlength="1000" placeholder="Where does this step take you?"')}
    <details class="more-details" ${hasDetails?'open':''}><summary>More details <span>Starting point, service, times & notes</span></summary><div class="fields">
    ${field('Starting location / address','from',s.from,'text',true,'maxlength="1000"')}
    ${field('Service / route number','service',s.service,'text',true,'maxlength="1000" placeholder="Airline, flight or bus number"')}
    ${field('Departure','departure',s.departure,'datetime-local')}${field('Arrival','arrival',s.arrival,'datetime-local')}
    <div class="field full form-help">Enter times as shown on your itinerary, in each location’s local time.</div>
    ${field('Booking reference','booking',s.booking,'text',true,'maxlength="1000"')}
    <label class="field full">Notes<textarea name="notes" maxlength="5000" placeholder="Platform, terminal, baggage or anything to remember…">${esc(s.notes)}</textarea></label>
    </div></details></div>${id?`<button type="button" class="btn danger delete-in-editor" data-action="delete-step" data-id="${id}">Delete step</button>`:''}${footer.replace('>Save</button>',id?'>Save changes</button>':'>Save travel step</button>')}</form>`,f=>{
      const data=Object.fromEntries(f);data.title=data.title.trim();
      if(!data.title){toast('Give this step a title.');return}
      const stepId=id||uid();
      if(mutate(ts=>{const t=ts.find(t=>t.id===active);if(id)Object.assign(t.steps.find(s=>s.id===id),data);else t.steps.push({...data,id:stepId,done:false})})){
        editor.close();showSavedStep(stepId,!!id);
      }
    });
}
function showSavedStep(id,edited){
  const s=trip().steps.find(s=>s.id===id);
  showDialog(edited?'Step updated':'Your next step is saved',`<div class="saved-step"><div class="saved-check" aria-hidden="true">✓</div><p class="eyebrow">${trip().steps.length} travel step${trip().steps.length===1?'':'s'} planned</p><h3>${esc(s.title)}</h3><p>${modes[s.mode]}${s.service?' · '+esc(s.service):''}</p>${s.to?`<p>↗ ${esc(s.to)}</p>`:''}${s.departure?`<p>Departs ${when(s.departure)}</p>`:''}<button class="icon-btn" data-action="edit-step" data-id="${id}">Edit this step</button><p class="sub">Add the next connection, or return to your checklist.</p><div class="form-footer"><button class="btn" data-action="finish-planning">Finish planning</button><button class="btn primary" data-action="new-step">＋ Add another step</button></div></div>`,null);
}
function askDelete(title,message,fn){showDialog(title,`<form><p class="sub">${message}</p><div class="form-footer"><button type="button" class="btn" data-cancel>Cancel</button><button class="btn danger" type="submit">Delete</button></div></form>`,()=>{if(fn())editor.close()})}
function example(open=true){
  const t=validate({trips:[EXAMPLE_PLAN]})[0];t.example=true;
  if(commit([t,...trips])){if(open){active=t.id;hideDone=false;filter='active'}render()}
}
const actions={'finish-planning':()=>{editor.close();render()},library:()=>{active=null;filter='active';query='';render()},archives:()=>{active=null;filter='archive';query='';render()},back:()=>{active=null;render()},'new-trip':()=>tripEditor(),'edit-trip':id=>tripEditor(id),open:id=>{active=id;hideDone=false;render()},'new-step':()=>stepEditor(),'edit-step':id=>stepEditor(id),duplicate:id=>{mutate(ts=>{const c=structuredClone(ts.find(t=>t.id===id));c.id=uid();c.title=c.title.slice(0,193)+' (copy)';c.archived=false;c.steps.forEach(s=>{s.id=uid();s.done=false});ts.unshift(c)});toast('Trip copied with a fresh checklist')},archive:()=>{mutate(ts=>{const t=ts.find(t=>t.id===active);t.archived=!t.archived});toast(trip().archived?'Trip archived':'Trip restored')},'delete-trip':()=>askDelete('Delete this trip?',`This removes the trip and every travel step ${cloud?.active?'from your synced library':'from this device'}. Export a backup first if you want to keep it.`,()=>{const id=active;const ok=mutate(ts=>ts.splice(ts.findIndex(t=>t.id===id),1));if(ok){active=null;render();toast('Trip deleted')}return ok}),'delete-step':id=>askDelete('Delete this step?','This removes the step from your trip.',()=>mutate(ts=>{const ss=ts.find(t=>t.id===active).steps;ss.splice(ss.findIndex(s=>s.id===id),1)})),up:id=>move(id,-1),down:id=>move(id,1),print:()=>{const wasHidden=hideDone;hideDone=false;render();const closed=[...document.querySelectorAll('details:not([open])')];closed.forEach(d=>d.open=true);window.print();closed.forEach(d=>d.open=false);hideDone=wasHidden;render()},export:()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),trips},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='waystep-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')},import:()=>document.querySelector('#import-file').click(),example,help:()=>showDialog('Make yourself at home',`<div class="help-content"><p><strong>Plan, then go.</strong> Create a trip, add each travel step, and tick the checkboxes as you finish. Use the arrows or drag steps to change the order.</p><p><strong>Local and synced libraries.</strong> Guest trips save in this browser. When you sign in, changes go to your synced library. Choose which guest trips to copy from the sync menu. Export backups regularly. Import adds trips to your library without replacing existing trips. Copies start with unchecked steps.</p><p><strong>Offline & installation.</strong> After the first online visit, saved trips work offline on this device. On supported browsers, choose “Install app” or “Add to Home Screen” from the browser menu. Install the app from your browser menu for easy access during your journey.</p><p><strong>Plan with AI.</strong> Connect a compatible AI app to send a draft, or import an existing plan as JSON. Review the draft before adding it. You can edit every step afterwards.</p><p><strong>Travel details.</strong> Enter your confirmed services and local departure/arrival times. Map links open Google Maps and may need internet. Waystep does not look up live schedules.</p>${installPrompt?'<button class="btn primary" id="install-btn">Install Waystep</button>':''}<p class="form-help">${storageOK?'Local saving is available.':'Local saving is unavailable. Recover browser storage before editing.'}</p></div>`,null)};
function move(id,delta){
  const current=trip(),i=current?.steps.findIndex(s=>s.id===id),j=i+delta;
  if(!current||i<0||j<0||j>=current.steps.length)return false;
  const title=current.steps[i].title;
  if(mutate(ts=>{const ss=ts.find(t=>t.id===active).steps;[ss[i],ss[j]]=[ss[j],ss[i]]})){
    const focusAction=j===0?'down':j===current.steps.length-1?'up':delta<0?'up':'down';
    document.querySelector(`[data-step="${id}"] [data-action="${focusAction}"]`)?.focus?.();
    toast(`${title} moved to step ${j+1}`);return true;
  }
  return false;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)actions[b.dataset.action]?.(b.dataset.id);if(e.target.id==='install-btn'&&installPrompt){installPrompt.prompt();installPrompt=null;editor.close()}});
document.addEventListener('change',e=>{if(e.target.dataset.check){mutate(ts=>{ts.find(t=>t.id===active).steps.find(s=>s.id===e.target.dataset.check).done=e.target.checked})}if(e.target.id==='hide-done'){hideDone=e.target.checked;render()}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;const pos=e.target.selectionStart;render();const x=document.querySelector('#search');x.focus();x.setSelectionRange(pos,pos)}});
document.querySelector('#import-file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;const account=cloud?.uid;try{if(file.size>10*1024*1024)throw Error('Backup is too large (maximum 10 MB).');const incoming=validate(JSON.parse(await file.text()));if(account!==cloud?.uid)throw Error('The active account changed. Please choose the backup again.');if(mutate(ts=>ts.push(...incoming)))toast(`Imported ${incoming.length} trip${incoming.length===1?'':'s'}`)}catch(err){toast(err instanceof SyntaxError?'This is not a valid JSON backup.':err.message)}};
function bindDrag(){document.querySelectorAll('[data-step]').forEach(el=>{el.ondragstart=e=>{if(e.target.closest('button,input,a,summary')){e.preventDefault();return}dragId=el.dataset.step;el.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragId)};el.ondragover=e=>{e.preventDefault();el.classList.add('drag-over')};el.ondragleave=()=>el.classList.remove('drag-over');el.ondragend=()=>{dragId=null;document.querySelectorAll('.dragging,.drag-over').forEach(x=>x.classList.remove('dragging','drag-over'))};el.ondrop=e=>{e.preventDefault();const id=dragId,target=el.dataset.step;if(id&&id!==target)mutate(ts=>{const ss=ts.find(t=>t.id===active).steps,from=ss.findIndex(s=>s.id===id),to=ss.findIndex(s=>s.id===target);const [s]=ss.splice(from,1);ss.splice(to,0,s)});dragId=null}})}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
window.addEventListener('online',render);window.addEventListener('offline',render);
window.addEventListener('storage',e=>{if(e.key===KEY&&!cloud?.active){toast('Plans changed in another tab. Reload to use the latest version.');storageOK=false}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>console.info('Offline cache unavailable on this origin.'));
if(firstVisit)example(false);
render();
